INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(48711, 'Ecclesiastes 4:15', 'Ecclesiastes', 4, 15, 'ما په دې غور وکړ چې څنګه به د دې ځوان په شاوخوا هغه ټول خلک چې د اسمان لاندې ژوند کوي، راټولیږي څوک چې د هغه پاچا په ځای به وروسته لوړ مقام ته ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_15.mp3', '', 1761754199, 1761754199),
(48712, 'Ecclesiastes 4:16', 'Ecclesiastes', 4, 16, 'دغه ځوان حتی که په بې‌شمېره خلکو باندې مشري هم وکړي، خو راتلونکي نسلونه به د هغه له کارونو څخه خوشحاله نه وي. په حقیقت کې، دا حالت هم لوګی او پوکی او په باد پسې منډې وهل دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes4_verse_16.mp3', '', 1761754199, 1761754199),
(48713, 'Ezekiel 10:1', 'Ezekiel', 10, 1, 'بیا مې هغه میدان ته وکتل چې د اسماني مخلوقاتو د سرونو دپاسه پروت ؤ او د هغو دپاسه یو شی ؤ چې هغه د داسې تخت په شان ښکاره کېده چې د لاجوردو نه جوړ شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_1.mp3', '', 1761754199, 1761754199),
(48714, 'Ezekiel 10:2', 'Ezekiel', 10, 2, 'څښتن هغه سړي ته چې د کتان کالي یې اغوستي وو، وویل: «د هغو چورلېدنکو ارابو په منځ کې چې د هغو مخلوقاتو لاندې دي، تېر شه او لاسونه دې د بلو سکارو نه ډک کړه او بیا هغه سکاره په ښار باندې وشینده.» نو هغه مې ولیده چې دننه لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_2.mp3', '', 1761754199, 1761754199),
(48715, 'Ezekiel 10:3', 'Ezekiel', 10, 3, 'کله چې هغه دننه لاړ، نو هغه مخلوقات د څښتن د کور جنوب خواته ولاړ وو او دننه حوېلۍ د ورېځې نه ډکه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_3.mp3', '', 1761754199, 1761754199),
(48716, 'Ezekiel 10:4', 'Ezekiel', 10, 4, 'د څښتن جلال د هغو مخلوقاتو نه راپورته شو او د هغه د کور د دروازې خولې ته روان شو. بیا کور د ورېځې نه ډک شو او حوېلۍ د څښتن د جلال د رڼا نه وځلېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_4.mp3', '', 1761754199, 1761754199),
(48717, 'Ezekiel 10:5', 'Ezekiel', 10, 5, 'د هغو مخلوقاتو د وزرونو اواز تر باندینۍ حوېلۍ پورې اورېدل کېده چې د مطلق قادر خدای د اواز په شان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_5.mp3', '', 1761754199, 1761754199),
(48718, 'Ezekiel 10:6', 'Ezekiel', 10, 6, 'کله چې څښتن هغه سړي ته چې د کتان کالي یې اغوستي وو، حکم وکړ چې د هغو اسماني مخلوقاتو لاندې د ارابو له منځ نه لږ اور راواخلي، نو هغه سړی دننه لاړ او د یوې ارابې په څنګ کې ودرېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_6.mp3', '', 1761754199, 1761754199),
(48719, 'Ezekiel 10:7', 'Ezekiel', 10, 7, 'د هغو مخلوقاتو څخه یو یې خپل لاس اوږد کړ او د هغه اور نه چې د هغوی په منځ کې بلېده، هغه لږې سکروټې راواخیستلې او د هغه سړي په لاسونو کې یې کېښودلې چې د کتان کالي یې اغوستي وو. هغه سړي دا سکروټې واخیستلې او لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_7.mp3', '', 1761754199, 1761754199),
(48720, 'Ezekiel 10:8', 'Ezekiel', 10, 8, 'ما ولیدل چې هر اسماني مخلوق د وزرونو لاندې د انسان د لاس په شان یو شی درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_8.mp3', '', 1761754199, 1761754199),
(48721, 'Ezekiel 10:11', 'Ezekiel', 10, 11, 'نو بې له تاوېدلو اسماني مخلوقاتو کولای شول چې له څلورو خواو نه هرې خواته چې وغواړي حرکت وکړي. کله به چې هغو مخلوقاتو حرکت کاوه، نو ارابې به هم بې له تاوېدلو ورسره تللې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_11.mp3', '', 1761754199, 1761754199),
(48722, 'Ezekiel 10:12', 'Ezekiel', 10, 12, 'د دې اسماني مخلوقاتو بدنونو، شاګانو، لاسونو، وزرونو او ارابو ټولو سترګې لرلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_12.mp3', '', 1761754199, 1761754199),
(48723, 'Ezekiel 10:13', 'Ezekiel', 10, 13, 'ما یو اواز واورېد چې ویل یې: «چورلېدونکې ارابې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_13.mp3', '', 1761754199, 1761754199),
(48724, 'Ezekiel 10:14', 'Ezekiel', 10, 14, 'هر اسماني مخلوق څلور مخونه لرل. لومړی مخ د غویي د مخ په شان ؤ، دوهم مخ د انسان، درېم مخ د زمري او څلورم مخ د عقاب د مخ په شان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_14.mp3', '', 1761754199, 1761754199),
(48725, 'Ezekiel 10:15', 'Ezekiel', 10, 15, 'دا هماغه ژوندي مخلوقات وو چې ما د خابور د سیند په غاړه لیدلي وو. کله به چې دا مخلوقات هوا ته پورته شول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_15.mp3', '', 1761754199, 1761754199),
(48726, 'Ezekiel 10:16', 'Ezekiel', 10, 16, 'او حرکت به یې کاوه، نو ارابې به هم ورسره تللې. کله به چې هغوی خپل وزرونه خلاص کړل چې والوزي، نو ارابې به هم ورسره تللې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_16.mp3', '', 1761754199, 1761754199),
(48727, 'Ezekiel 10:17', 'Ezekiel', 10, 17, 'کله به چې هغه مخلوقات ودرېدل، نو ارابې به هم ودرېدلې او کله به چې هغه مخلوقات الوتل، نو ارابې به هم ورسره تللې، ځکه چې دې مخلوقاتو به په هغو باندې واک درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_17.mp3', '', 1761754199, 1761754199),
(48728, 'Ezekiel 10:18', 'Ezekiel', 10, 18, 'بیا د څښتن جلال د هغه د کور د دروازې د خولې نه لاړ او د اسماني مخلوقاتو دپاسه ودرېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_18.mp3', '', 1761754199, 1761754199),
(48729, 'Ezekiel 10:19', 'Ezekiel', 10, 19, 'هغوی خپل وزرونه خپاره کړل او ما ورته کتل چې هغوی د ځمکې نه پورته شول او ارابې هم ورسره لاړلې. هغوی د څښتن د کور د ختیځې خوا دروازې سره ودرېدل او د اسراییلو د خدای جلال د هغوی د سر دپاسه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_19.mp3', '', 1761754199, 1761754199),
(48730, 'Ezekiel 10:20', 'Ezekiel', 10, 20, 'ما هغه مخلوقات وپېژندل. دا هماغه اسماني مخلوقات وو چې ما د خابور د سیند په غاړه د اسراییلو د خدای د تخت لاندې لیدلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_20.mp3', '', 1761754199, 1761754199),
(48731, 'Ezekiel 10:21', 'Ezekiel', 10, 21, 'هغوی هر یو څلور مخونه او څلور وزرونه لرل او د هر وزر لاندې د انسان د لاس په شان یو شی ښکاره کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_21.mp3', '', 1761754199, 1761754199),
(48732, 'Ezekiel 10:22', 'Ezekiel', 10, 22, 'د هغوی مخونه کټ مټ د هغو مخونو په شان وو کوم چې ما د خابور د سیند په غاړه لیدلي وو. هر اسماني مخلوق سیده حرکت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel10_verse_22.mp3', '', 1761754199, 1761754199),
(48733, 'Zechariah 10:1', 'Zechariah', 10, 1, 'مالِک خُدائ ته په سپرلى کښې د باران دپاره سوال وکړئ. ځکه چې دا مالِک خُدائ دے چې طوفانى وريځې رالېږى. هغه باران ورَوى او د هر چا دپاره په پټو کښې شنۀ بوټى پېدا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_1.mp3', '', 1761754199, 1761754199),
(48734, 'Zechariah 10:2', 'Zechariah', 10, 2, 'بُتان د فريب خبرې کوى، فالګر هغه رويا ګورى چې دروغ وى، هغوئ د خوبونو غلط تعبير کوى، او هغوئ بې‌فائدې تسلى ورکوى. نو ځکه خلق د ورکو شوو ګډو په شان سرګردانه ګرځى. په هغوئ ځکه ظلم کيږى چې شپون يې نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_2.mp3', '', 1761754199, 1761754199),
(48735, 'Zechariah 10:3', 'Zechariah', 10, 3, '”زما غصه د شپونکو خلاف زياته شوې ده، او زۀ به حکمرانانو له سزا ورکړم، ځکه چې مالِک خُدائ به د خپلې رمې حفاظت کوى، د يهوداه د قوم، او هغوئ به لکه د جنګ د فخر آس جوړ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_3.mp3', '', 1761754199, 1761754199),
(48736, 'Zechariah 10:4', 'Zechariah', 10, 4, 'د يهوداه نه به د ګوټ کاڼے، د خېمې موږے، د جنګ لينده جوړه شى، د هغې نه به هر يو حکمران راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_4.mp3', '', 1761754199, 1761754199),
(48737, 'Zechariah 10:5', 'Zechariah', 10, 5, 'هغوئ به يو ځائ لکه د طاقتورو خلقو په شان په جنګ کښې دشمنان د کوڅې په خټو کښې د پښو لاندې کړى. ځکه چې مالِک خُدائ د هغوئ سره دے، هغوئ به جنګ وکړى او د آسونو سوارۀ به لاندې راوغورزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_5.mp3', '', 1761754199, 1761754199),
(48738, 'Zechariah 10:6', 'Zechariah', 10, 6, 'زۀ به د يهوداه خلق تکړه کړم او د يوسف قوم به بچ کړم. زۀ به هغوئ بيا آباد کړم ځکه چې زۀ په هغوئ رحم کوم. هغوئ به داسې وى لکه چې کله ما هغوئ نۀ وى رد کړى. ځکه چې زۀ مالِک خُدائ د هغوئ خُدائ پاک يم، او زۀ به د هغوئ دُعا ته جواب ورکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_6.mp3', '', 1761754199, 1761754199),
(48739, 'Zechariah 10:7', 'Zechariah', 10, 7, 'اِفرائيميان به لکه د جنګيالو په شان شى، او د هغوئ زړونه به داسې خوشحاله وى لکه چې مے يې څښلى وى. د هغوئ اولاد به دا وګورى او خوشحاله به وى، د هغوئ زړونه به په مالِک خُدائ کښې خوشحاله وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_7.mp3', '', 1761754199, 1761754199),
(48740, 'Zechariah 10:8', 'Zechariah', 10, 8, 'زۀ به هغوئ ته شپيلے ووهم او يو ځائ ته به يې راغونډ کړم. يقيناً زۀ به هغوئ آزاد کړم، هغوئ به بې‌شمېره کړم څنګه چې مخکښې وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_8.mp3', '', 1761754199, 1761754199),
(48741, 'Zechariah 10:9', 'Zechariah', 10, 9, 'اګر کۀ ما هغوئ په قومونو کښې خوارۀ وارۀ کړى دى خو په لرې مُلکونو کښې به هغوئ ما ياد ساتى. هغوئ او د هغوئ بچى به ژوندى پاتې شى، او واپس به راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_9.mp3', '', 1761754199, 1761754199),
(48742, 'Zechariah 10:10', 'Zechariah', 10, 10, 'زۀ به هغوئ واپس راولم د مِصر نه او هغوئ به د اسور نه راجمع کړم. زۀ به هغوئ راولم جِلعاد او لبنان ته، او هلته به د هغوئ ټولو دپاره کافى ځايونه نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_10.mp3', '', 1761754199, 1761754199),
(48743, 'Zechariah 10:11', 'Zechariah', 10, 11, 'هغوئ به د مصيبت د سمندر نه تېر شى، چپې وهونکے سمندر به خاموش شى، او د نيل درياب ژورې اوبۀ به اوچې شى. د اسور غرور به راښکته شى، او د مِصر شاهى طاقت به ختم شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_11.mp3', '', 1761754199, 1761754199),
(48744, 'Zechariah 10:12', 'Zechariah', 10, 12, 'زۀ به هغوئ له په مالِک خُدائ کښې طاقت ورکړم، او د هغۀ په نوم به هغوئ روان وى،“ مالِک خُدائ فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah10_verse_12.mp3', '', 1761754199, 1761754199),
(48745, 'Numbers 7:1', 'Numbers', 7, 1, 'کله چې موسی د سپېڅلې خېمې د ودرولو څخه وزګار شو، نو خېمه او د هغې ټول سامان او د قربانۍ ځای او د هغه ټول سامان یې مسح کړ او هغه یې څښتن ته وقف کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers7_verse_1.mp3', '', 1761754199, 1761754199),
(48746, 'Numbers 7:2', 'Numbers', 7, 2, 'بیا د اسراییلو دولس قبیلوي مشران یعنې هماغه کسان چې د خلکو د سرشمېرنې مشري یې په غاړه وه، سپېڅلې خېمې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers7_verse_2.mp3', '', 1761754199, 1761754199),
(48747, 'Numbers 7:3', 'Numbers', 7, 3, 'د هغو سوغاتونو سره راغلل چې د څښتن دپاره وو. هغوی شپږ ګاډۍ ګانې او دولس غویان راوړل، هر مشر یو یو غویی او دوو مشرانو یوه یوه ګاډۍ راوستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers7_verse_3.mp3', '', 1761754199, 1761754199),
(48748, 'Numbers 7:4', 'Numbers', 7, 4, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers7_verse_4.mp3', '', 1761754199, 1761754199),
(48749, 'Numbers 7:5', 'Numbers', 7, 5, '«دا سوغاتونه د هغوی څخه قبول کړه چې د سپېڅلې خېمې په کار کې ورڅخه ګټه واخیستل شي او هغه لاویانو ته د هغه کار دپاره ورکړه چې هر یو یې په سپېڅلې خېمه کې سرته رسوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers7_verse_5.mp3', '', 1761754199, 1761754199),
(48750, 'Numbers 7:6', 'Numbers', 7, 6, 'نو موسی ګاډۍ ګانې او غویان واخیستل او هغه یې لاویانو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers7_verse_6.mp3', '', 1761754199, 1761754199),
(48751, 'Numbers 7:9', 'Numbers', 7, 9, 'خو قهاتیانو ته یې هېڅ ورنه کړل، ځکه چې هغوی د هغو سپېڅلو شیانو مسوولان وو چې باید په خپلو اوږو باندې یې یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers7_verse_9.mp3', '', 1761754199, 1761754199),
(48752, 'Numbers 7:10', 'Numbers', 7, 10, 'کله چې د قربانۍ ځای مسح کړای شو، مشرانو خپلې نذرانې د هغه د وقف کولو دپاره راوړلې او هغه یې د قربانۍ د ځای په مخکې وړاندې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers7_verse_10.mp3', '', 1761754199, 1761754199),
(48753, 'Numbers 7:11', 'Numbers', 7, 11, 'څښتن موسی ته وویل: «مشرانو ته ووایه چې تر دولسو ورځو پورې دې یو یو مشر هره ورځ خپله نذرانه د قربانۍ د ځای د وقف کولو دپاره راوړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers7_verse_11.mp3', '', 1761754199, 1761754199),
(48754, 'Numbers 7:89', 'Numbers', 7, 89, 'کله به چې موسی غوښتل چې د څښتن سره خبرې وکړي، نو سپېڅلې خېمې ته به ورننوت. هلته به هغه د دوو اسماني مخلوقاتو له منځ څخه د کفارې د پوښ دپاسه چې د لوظ په صندوق باندې پروت ؤ، د څښتن غږ اورېده چې د هغه سره یې خبرې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers7_verse_89.mp3', '', 1761754199, 1761754199),
(48755, 'Ezekiel 27:1', 'Ezekiel', 27, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_1.mp3', '', 1761754199, 1761754199),
(48756, 'Ezekiel 27:2', 'Ezekiel', 27, 2, '«ای فاني انسانه، د صور دپاره د ویر یوه سندره ووایه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_2.mp3', '', 1761754199, 1761754199),
(48757, 'Ezekiel 27:3', 'Ezekiel', 27, 3, 'د هغه ښار دپاره چې د بحیرې بندرونه لري او د بحیرې د غاړې د هېوادنو او د جزیرو د خلکو دپاره د سوداګرۍ مرکز دی، هغه ته ووایه چې څښتن تعالی داسې وایي: ‹ای صوره، وهلې لافې تا چې ښایست مې دی پوره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_3.mp3', '', 1761754199, 1761754199),
(48758, 'Ezekiel 27:4', 'Ezekiel', 27, 4, 'پوله ده ستا د بحیرې په زړه کې ستا جوړوونکو پوره کړی ستا ښایست دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_4.mp3', '', 1761754199, 1761754199),
(48759, 'Ezekiel 27:5', 'Ezekiel', 27, 5, 'ته وې په شان د بحیرې د کشتۍ دوی جوړولې ستا تختې د حرمون د غره د سروې له ونو او دوی جوړوله ستا ستنه د لبنان د سبر له ونې څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_5.mp3', '', 1761754199, 1761754199),
(48760, 'Ezekiel 27:6', 'Ezekiel', 27, 6, 'د باشان د څېړۍ له ونو هغوی جوړ کړل راشپېلونه د کشتۍ هغوی جوړ کړلو ستا فرش د قبرس د نښتر له ونو او هغه یې سینګار کړلو د فیل په غاښو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_6.mp3', '', 1761754199, 1761754199),
(48761, 'Ezekiel 27:7', 'Ezekiel', 27, 7, 'د ښه کتان څخه یې جوړ کړل بادوانونه د ستا او د مصر د ګلدوزي شوي کتان څخه چې ستا نښه یې له لېرې په اسانه پېژندله وه جوړه شوې ستا چترۍ د ډېر ښه رخت څخه چې هغه ؤ بانجاني رنګی رخت د قبرس د جزیرې څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_7.mp3', '', 1761754199, 1761754199),
(48762, 'Ezekiel 27:8', 'Ezekiel', 27, 8, 'راشپېل وهونکي وو ستا د صیدون او د ارواد له ښارونو څخه ای صوره، ستا چلوونکي وو د کشتۍ ماهران خلک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_8.mp3', '', 1761754199, 1761754199),
(48763, 'Ezekiel 27:9', 'Ezekiel', 27, 9, 'وو ماهر نجاران د کشتۍ‌ګانو د جبال با تجربه خلک چې کوله یې رغونه د کشتۍ سوداګري کوله په بازارونو کې ستا د بحیرې د ټولو کشتیو چلوونکو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_9.mp3', '', 1761754199, 1761754199),
(48764, 'Ezekiel 27:10', 'Ezekiel', 27, 10, 'د فارس، لیدیا او لیبیا عسکرو به ستا په لښکر کې خدمت کاوه. هغوی به خپل سپرونه او خپلې د زغرو خولۍ ستا شاوخوا ځوړندولې. دا هغه خلک وو چې د هغو په وسیله تا شان او شوکت تر‌لاسه کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_10.mp3', '', 1761754199, 1761754199),
(48765, 'Ezekiel 27:11', 'Ezekiel', 27, 11, 'د ارواد او د حیلک عسکرو ستا شاوخوا دېوالونه او د جماد سړیو ستا برجونه ساتل. هغوی به خپل سپرونه ستا په دېوالونو باندې ځوړندول. دا هغه خلک وو چې ستا ښایست یې پوره کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_11.mp3', '', 1761754199, 1761754199),
(48766, 'Ezekiel 27:12', 'Ezekiel', 27, 12, 'د ترشیش خلکو به تا سره سوداګري کوله او ستا د پرېمانه سوداګرۍ مالونو په بدل کې به یې سپین زر، اوسپنه، حلبي او سرپ درکول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_12.mp3', '', 1761754199, 1761754199),
(48767, 'Ezekiel 27:13', 'Ezekiel', 27, 13, 'یونان، توبال او ماشک به ستا سره سوداګري کوله او ستا د مالونو په بدل کې به یې غلامان او د برنجو لوښي درکول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_13.mp3', '', 1761754199, 1761754199),
(48768, 'Ezekiel 27:14', 'Ezekiel', 27, 14, 'د بیت‌توجرمه څخه ستا د مالونو په بدل کې به یې بار وړونکي اسونه، جنګي اسونه او قچرې درکولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_14.mp3', '', 1761754199, 1761754199),
(48769, 'Ezekiel 27:15', 'Ezekiel', 27, 15, 'د رودس خلکو به تا سره د سوداګرۍ کاروبار کاوه. د بحیرې په غاړو او په جزیرو باندې د پرتو وطنونو خلکو به تا سره د سوداګرۍ راکړه او ورکړه کوله او ستا د مالونو په بدل کې به یې د فیل غاښونه او د ابنوس تور لرګي درکول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_15.mp3', '', 1761754199, 1761754199),
(48770, 'Ezekiel 27:16', 'Ezekiel', 27, 16, 'د سوریې خلکو به تا سره سوداګري کوله، ځکه چې په تا کې هر ډول مالونه پیدا کېدل. هغوی به ستا د مالونو په بدل کې تاته زمرد، بانجاني رنګه رختونه، ګلدوزي شوي شیان، د کتان ښه رختونه، د بحیرې مرجان او یاقوت درکول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_16.mp3', '', 1761754199, 1761754199),
(48771, 'Ezekiel 27:17', 'Ezekiel', 27, 17, 'د یهودا او د اسراییلو خلکو به ستا د مالونو په بدل کې تاته د منیت څخه غنم، اینځر، شات، د زیتونو تېل او ملهم درکول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_17.mp3', '', 1761754199, 1761754199),
(48772, 'Ezekiel 27:20', 'Ezekiel', 27, 20, 'د ددان خلکو به ستا د مال په بدل کې تاته د اسونو د زین پوښونه درکول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_20.mp3', '', 1761754199, 1761754199),
(48773, 'Ezekiel 27:21', 'Ezekiel', 27, 21, 'عربانو او د قیدار واکمنانو به ستا د مالونو په بدل کې وري، پسونه او وزې په تا خرڅولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_21.mp3', '', 1761754199, 1761754199),
(48774, 'Ezekiel 27:22', 'Ezekiel', 27, 22, 'ستا د مالونو په بدل کې به د شیبا او رعمه سوداګرانو هر ډول عطرونه، قیمتي تیږې او سره زر درکول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_22.mp3', '', 1761754199, 1761754199),
(48775, 'Ezekiel 27:23', 'Ezekiel', 27, 23, 'د حران، کنه عدن، آشور او د کلمد ښارونو او د شیبا سوداګرانو به تا سره سوداګري کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_23.mp3', '', 1761754199, 1761754199),
(48776, 'Ezekiel 27:24', 'Ezekiel', 27, 24, 'هغوی ستا سره د ښکلي کاليو، بانجاني رنګه او ګلدوزي شوي چپنو، رنګه قالینو او ښه جوړ شوي تارونو او رسۍ‌ګانو سوداګري کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_24.mp3', '', 1761754199, 1761754199),
(48777, 'Ezekiel 27:25', 'Ezekiel', 27, 25, 'د ترشیش بحري کشتۍ‌ګانو به ستا د سوداګرۍ مالونه ستا په خاطر وړل. د بحیرې منځ کې وې ته هغې کشتۍ په شان چې وي ډکه په درنو مالونو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_25.mp3', '', 1761754199, 1761754199),
(48778, 'Ezekiel 27:26', 'Ezekiel', 27, 26, 'کله چې یووړلې راشپیل وهونکو ستا د بحیرې منځ ته نو ته ماته کړلې د ختیځ باد د بحیرې په منځ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_26.mp3', '', 1761754199, 1761754199),
(48779, 'Ezekiel 27:27', 'Ezekiel', 27, 27, 'ستا ټوله شتمني او ستا مالونه ستا ټول کشتیوانان نجاران او سوداګران ستا د کشتیو ستا هر عسکر چې په کشتۍ کې سپور ؤ ټول شول ډوب په بحیره کې هغه ورځ چې شوه ډوبه ستا کشتۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_27.mp3', '', 1761754199, 1761754199),
(48780, 'Ezekiel 27:28', 'Ezekiel', 27, 28, 'د ډوبېدونکو کشتیوانانو په چیغو به ولړزیږي د بحیرې غاړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_28.mp3', '', 1761754199, 1761754199),
(48781, 'Ezekiel 27:29', 'Ezekiel', 27, 29, 'پرېږدي ټول راشپېل وهونکي کشتۍ خپلې کشتیوانان دي ټول ولاړ د بحیرې په غاړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_29.mp3', '', 1761754199, 1761754199),
(48782, 'Ezekiel 27:30', 'Ezekiel', 27, 30, 'وهي چیغې هغوی ټول او سخت ژاړي په خاطر ستا بادوي خپلو سرونو باندې خاورې او په ایرو کې رغړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_30.mp3', '', 1761754199, 1761754199),
(48783, 'Ezekiel 27:31', 'Ezekiel', 27, 31, 'ستا په خاطر هغوی خریي خپل سرونه هغوی اغوستي دي د ویر کالي تاته سخت ژاړي د زړه له درده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_31.mp3', '', 1761754199, 1761754199),
(48784, 'Ezekiel 27:32', 'Ezekiel', 27, 32, 'تاته کوي انګولا او وایي سندرې د ماتم داسې ښار شته لکه د صور په شان چې اوس خاموش دی د بحیرې په تل کې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_32.mp3', '', 1761754199, 1761754199),
(48785, 'Ezekiel 27:33', 'Ezekiel', 27, 33, 'کله چې تلل بهر ملکونو ته مالونه ستا پوره کول ضرورتونه به تا د ډېرو قومونو ستا په پرېمانه شتمنۍ او مالونو باندې تا شتمن کړل د نړۍ پاچاهان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_33.mp3', '', 1761754199, 1761754199),
(48786, 'Ezekiel 27:34', 'Ezekiel', 27, 34, 'اوس ماته شوې یې ته په بحیرې کې ډوبه شوې یې ته د بحیرې په تل کې ستا مالونه او ټول خلک چې به یې کار کاوه په تا کې تا سره ډوب شول ټول په بحیرې کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_34.mp3', '', 1761754199, 1761754199),
(48787, 'Ezekiel 27:35', 'Ezekiel', 27, 35, 'د بحیرې په غاړه او جزیرو کې چې اوسیږي څوک پاتې کیږي حیران د قومونو تجاران ځکه چې بد دی څومره ستا سرنوشت هم وېرېدلي وو سخت پاچاهان د هغوی په څېرو کې د هغوی ښکاره کیږي وېره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_35.mp3', '', 1761754199, 1761754199),
(48788, 'Ezekiel 27:36', 'Ezekiel', 27, 36, 'پاتې کیږي هک حیران د قومونو تجاران هغوی وېریږي ځکه چې بد دی څومره ستا سرنوشت له منځه تللی یې ته د تل دپاره›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel27_verse_36.mp3', '', 1761754199, 1761754199),
(48789, 'Numbers 35:1', 'Numbers', 35, 1, 'په داسې حال کې چې اسراییلیانو د موآب په ډاګونو کې د اردن د سیند په بله غاړه اریحا ته مخامخ خېمې ودرولې، څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_1.mp3', '', 1761754199, 1761754199),
(48790, 'Numbers 35:2', 'Numbers', 35, 2, '«اسراییلیانو ته ووایه د هغه جایداد څخه چې هغوی یې تر لاسه کوي، باید لاویانو ته د اوسېدلو دپاره څو ښارونه او د هغو شاوخوا څړځایونه ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_2.mp3', '', 1761754199, 1761754199),
(48791, 'Numbers 35:3', 'Numbers', 35, 3, 'دا ښارونه به د لاویانو وي او هغوی به هلته اوسیږي. د څړځایونه به د هغوی د غویانو او د هغوی د نورو ټولو حیواناتو دپاره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_3.mp3', '', 1761754199, 1761754199),
(48792, 'Numbers 35:4', 'Numbers', 35, 4, 'څړځای باید د ښار د باندیني دېوالونو څخه هرې خواته څلورنیم سوه متره وغزول شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_4.mp3', '', 1761754199, 1761754199),
(48793, 'Numbers 35:5', 'Numbers', 35, 5, 'ترڅو یوه مربع شکله سیمه جوړه شي چې هره خوا یې نهه سوه متره وي او ښار به یې په منځ کې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_5.mp3', '', 1761754199, 1761754199),
(48794, 'Numbers 35:6', 'Numbers', 35, 6, 'شپږ ښارونه چې تاسو یې هغوی ته ورکوئ هغه به د پناه اخیستلو ښارونه وي او یو کس چې یو څوک یې په سهوې سره وژلی وي، کولای شي چې هلته وتښتي. خو تاسو باید لاویانو ته دوه څلوېښت نور ښارونه ورکړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_6.mp3', '', 1761754199, 1761754199),
(48795, 'Numbers 35:7', 'Numbers', 35, 7, 'نو هغوی به د شاوخوا څړځایونو سره ټول اته څلوېښت ښارونه ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_7.mp3', '', 1761754199, 1761754199),
(48796, 'Numbers 35:8', 'Numbers', 35, 8, 'د لاویانو د ښارونو شمېر باید په هره قبیله کې د هغې د سیمې د اندازې له مخې معلوم کړای شي. لویې قبیلې ته به زیات ښارونه او کوچنۍ قبیلې ته به کم ښارونه ورکړای شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_8.mp3', '', 1761754199, 1761754199),
(48797, 'Numbers 35:9', 'Numbers', 35, 9, 'بیا څښتن موسی ته وویل چې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_9.mp3', '', 1761754199, 1761754199),
(48798, 'Numbers 35:10', 'Numbers', 35, 10, 'د اسراییلو قوم ته داسې ووایي: «کله چې تاسو د اردن د سیند څخه تېر شئ او د کنعان خاورې ته ورننوځئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_10.mp3', '', 1761754199, 1761754199),
(48799, 'Numbers 35:11', 'Numbers', 35, 11, 'د پناه اخیستلو ښارونه غوره کړئ چې داسې کس د ساتنې دپاره ورتښتېدلی شي چې یو څوک یې په سهوې سره وژلی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_11.mp3', '', 1761754199, 1761754199),
(48800, 'Numbers 35:12', 'Numbers', 35, 12, 'هغه به په هغه ځای کې د وژل شوي کس د خپلوانو د یو کس څخه چې د بدل اخیستلو په لټه کې وي، په امن کې اوسي. هېڅوک چې هغه په قتل باندې تورن شوی وي د محاکمې څخه پرته نه شي وژل کېدای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_12.mp3', '', 1761754199, 1761754199),
(48801, 'Numbers 35:13', 'Numbers', 35, 13, 'شپږ ښارونه غوره کړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_13.mp3', '', 1761754199, 1761754199),
(48802, 'Numbers 35:14', 'Numbers', 35, 14, 'درې د اردن ختیځې خواته او درې د کنعان په خاوره کې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_14.mp3', '', 1761754199, 1761754199),
(48803, 'Numbers 35:15', 'Numbers', 35, 15, 'دا به د اسراییلیانو او هغو پردیو خلکو دپاره چې په موقت یا تلپاتې توګه اوسیږي د پناه اخیستلو ځایونه وي. هرڅوک چې په سهوې سره یو کس مړ کړي، هغه کولای شي چې د دې ښارونو څخه یو ښار ته وتښتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_15.mp3', '', 1761754199, 1761754199),
(48804, 'Numbers 35:19', 'Numbers', 35, 19, 'د وژل شوي کس یو ډېر نژدې خپلوان دا مسوولیت لري چې قاتل ووژني. کله چې هغه پیدا کړي، باید ویې وژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_19.mp3', '', 1761754199, 1761754199),
(48805, 'Numbers 35:20', 'Numbers', 35, 20, 'که چېرې څوک د کوم کس سره کینه لري او هغه په ټېل وهلو یا په یو شي باندې په ویشتلو سره مړ کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_20.mp3', '', 1761754199, 1761754199),
(48806, 'Numbers 35:21', 'Numbers', 35, 21, 'یا هغه په سوک ووهي، هغه د هغه کس د قتل په اړه مجرم دی او باید ووژل شي. د وژل شوي کس یو ډېر نژدې خپلوان دا مسوولیت لري چې قاتل ووژني. کله چې هغه راپیدا کړي، نو باید ویې وژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_21.mp3', '', 1761754199, 1761754199),
(48807, 'Numbers 35:22', 'Numbers', 35, 22, 'خو فرض کړئ څوک په سهوې سره یو داسې کس مړ کړي چې د هغه سره کینه نه لري، که هغه په ټېل وهلو وي یا په کوم شي باندې په ویشتلو سره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_22.mp3', '', 1761754199, 1761754199),
(48808, 'Numbers 35:23', 'Numbers', 35, 23, 'یا د هغه فکر نه وي او یو داسې سړی په تیږه باندې په ویشتلو مړ کړي چې د هغه نیت نه وي چې هغه ژوبل کړي او د هغه دښمن نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_23.mp3', '', 1761754199, 1761754199),
(48809, 'Numbers 35:24', 'Numbers', 35, 24, 'نو په داسې حالاتو کې دې د هغه ځای خلک د هغه چا په حق کې پرېکړه وکړي چې کس یې مړ کړی دی، نه د مړي د خپلوانو څخه د هغه کس په حق کې چې د بدل اخیستلو په لټه کې دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_24.mp3', '', 1761754199, 1761754199),
(48810, 'Numbers 35:25', 'Numbers', 35, 25, 'ټولنه باید هغه سړی چې په قتل باندې تورن دی د وژل شوي کس د خپلوان څخه خلاص کړي او هغه باید د پناه اخیستنې هغه ښار ته چې هغه ورتښتېدلی ؤ، بېرته ولېږي. هغه باید د لوی کاهن تر مړینې پورې په هغه ښار کې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers35_verse_25.mp3', '', 1761754199, 1761754199);